args.ReplacementContent:
"/* ==================== PROGRESS BELAJAR - SERTIFIKAT AKADEMI ==================== */
.cert-grid {
  display: grid;
  grid-template-columns: repeat(1, 1fr);
  gap: 1.5rem;
  margin-top: 16px;
}

@media (min-width: 768px) {
  .cert-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

.cert-card {
  background-color: #FFFFFF;
  border-radius: 12px;
  box-shadow: 0 4px 6px -1px rgba(0,0,0,0.05);
  padding: 20px;
}

.cert-badge {
  display: inline-block;
  padding: 4px 12px;
  border-radius: 9999px;
  font-size: 0.75rem;
  font-weight: 600;
  white-space: nowrap;
  text-align: center;
}

.cert-badge-danger {
  background-color: #FEF2F2;
  color: #DC2626;
}

.cert-badge-success {
  background-color: #ECFDF5;
  color: #059669;
}

.btn-print-cert {
  width: 100%;
  padding: 8px 12px;
  border: none;
  border-radius: 6px;
  font-weight: 600;
  font-size: 13px;
  transition: background-color 0.2s ease;
}

.btn-print-cert:disabled {
  background-color: #E5E7EB;
  color: #4B5563;
  box-shadow: none;
  cursor: not-allowed;
}

.btn-print-cert:not(:disabled) {
  background-color: #0056A3;
  color: #ffffff;
  cursor: pointer;
}

.btn-print-cert:not(:disabled):hover {
  background-color: #004482;
}"

