"window.renderTrainerMaterials = function() {
    const tbody = document.getElementById('trainer-material-rows');
    if (!tbody) return;

    let materials = JSON.parse(localStorage.getItem('pa_materials')) || [];
    if (materials.length === 0) {
        materials = [
            { id: "mat-1", title: "Asuransi Jiwa Dasar", cat: "Dasar Asuransi", quizCount: 5 },
            { id: "mat-2", title: "Asuransi Properti Komersial", cat: "Asuransi Properti", quizCount: 10 }
        ];
        localStorage.setItem('pa_materials', JSON.stringify(materials));
    }

    tbody.innerHTML = "";
    materials.forEach(m => {
        if (!m) return;

        const judulTeks = m.title || m.judul || 'Tanpa Judul';
        const kategoriTeks = m.kategori || m.kategoriMateri || m.cat || 'Tanpa Kategori';
        const jumlahKuis = (m.kuis && Array.isArray(m.kuis)) ? m.kuis.length : (m.quizCount || 0);

        tbody.innerHTML += `
            <tr>
                <td><strong>${judulTeks}</strong></td>
                <td>${kategoriTeks} <br><small style="color:var(--text-muted); font-weight:600;">(${m.level || 'Basic'})</small></td>
                <td>${jumlahKuis} Soal</td>
                <td>
                    <button class="btn-secondary" style="padding:4px 8px; font-size:11px;" onclick="alert('Demo: Hapus modul ini')">Hapus</button>
                </td>
            </tr>
        `;
    });
};"

